using UnityEngine;
using UnityEngine.Rendering;
namespace BWVR {
public sealed partial class WorldBrush {
 public const float WhirlwindCost=1,WhirlwindInterval=.1f,WhirlwindRadius=16;
 readonly LineRenderer[] spiral=new LineRenderer[3];
 public int WhirlwindAffected{get;private set;}
 void BuildWhirlwind(){for(int i=0;i<spiral.Length;i++){var go=new GameObject("Whirlwind air ribbon "+i);go.transform.SetParent(transform,false);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=material;line.useWorldSpace=false;line.positionCount=64;line.widthMultiplier=nav.Scale*.25f;line.startColor=new Color(.7f,.9f,1,.65f);line.endColor=new Color(.85f,.95f,1,.05f);line.shadowCastingMode=ShadowCastingMode.Off;line.receiveShadows=false;line.enabled=false;spiral[i]=line;}}
 bool InWhirlwind(Vector3 at,Vector3 point){var d=(at-point)/nav.Scale;return d.y>=-2&&d.y<=22&&d.x*d.x+d.z*d.z<=WhirlwindRadius*WhirlwindRadius;}
 // Velocities are in game units in both private physics scenes, independent of tabletop zoom.
 static Vector3 SwirlVelocity(Vector3 offset,Vector3 velocity){var flat=new Vector3(offset.x,0,offset.z);var inward=flat.sqrMagnitude>.01f?-flat.normalized:Vector3.right;var tangent=Vector3.Cross(Vector3.up,-inward);var desired=tangent*8+inward*Mathf.Clamp(flat.magnitude-6,-3,7)+Vector3.up*Mathf.Clamp((10-offset.y)*2,-6,12);return velocity+Vector3.ClampMagnitude((desired-velocity)*.35f,2.5f);}
 bool WhirlwindBall(BeachBall ball)=>ball!=null&&ball.Body!=null&&!ball.Body.isKinematic&&!Reserved(ball.GetComponent<CarryItem>())&&!ball.FetchReserved&&ball.Player==null&&!ball.PeerGame&&!ball.BuildBowlPending&&!ball.BowlCreaturePending&&ball.Puzzle?.Active!=true&&ball.Bowling?.Active!=true&&ball.Goals?.Active!=true;
 bool WhirlwindBlock(ConstructionBlock block)=>block!=null&&block.Body!=null&&!block.Body.isKinematic&&!block.Attached&&block.VillagerOwner==null&&!block.Site.IsBridge&&!block.Site.Paused&&!block.Site.Locked&&!block.Site.BuildBowlReserved&&block.Site.Repairer==null&&block.Site.Visitor==null&&block.Site.Requester==null&&!Reserved(block.Item);
 int WhirlwindObjects(Vector3 point,bool apply){int count=0;
  foreach(var ball in windBalls){if(count>=8)break;if(!WhirlwindBall(ball)||!InWhirlwind(nav.ToWorld(ball.Body.position),point))continue;if(apply){var desired=SwirlVelocity((nav.ToWorld(ball.Body.position)-point)/nav.Scale,ball.Body.linearVelocity);ball.EnvironmentalImpulse(desired-ball.Body.linearVelocity);}count++;}
  foreach(var block in windBlocks){if(count>=8)break;if(!WhirlwindBlock(block)||!InWhirlwind(block.Site.World(block.Body.position),point))continue;if(apply){var rotation=block.Site.transform.rotation;var velocity=rotation*block.Body.linearVelocity;var desired=SwirlVelocity((block.Site.World(block.Body.position)-point)/nav.Scale,velocity);block.Body.linearVelocity=Quaternion.Inverse(rotation)*desired;block.Body.angularVelocity=Vector3.ClampMagnitude(block.Body.angularVelocity+Vector3.up*.4f,4);block.Body.WakeUp();}count++;}
  return count;
 }
 public bool CanWhirlwind(Vector3 point,out string reason){EnsureSeason();reason="";if(Season.paused||miracles.Suspended){reason="Paused";return false;}if(!GroundPoint(point)){reason="Aim at dry island ground";return false;}if(!miracles.CanAfford(WhirlwindCost)){reason="Not enough spiritual energy";return false;}if(WhirlwindObjects(point,false)==0){reason="Aim near free toys or loose blocks";return false;}return true;}
 public bool WhirlwindPulse(Vector3 point){EnsureSeason();if(Season.Hybrid.time<nextPulse){Reason="Whirlwind is settling";return false;}if(!CanWhirlwind(point,out var reason)){Reason=reason;return false;}WhirlwindAffected=WhirlwindObjects(point,true);if(WhirlwindAffected==0)return false;miracles.SpendEnergy(WhirlwindCost);nextPulse=Season.Hybrid.time+WhirlwindInterval;Pulses++;Point=point;Reason="";creature.InvalidateLesson("Player whirlwind is not creature work");if(strokePulses==0){Season.Hybrid.Evidence.Add(Season.Hybrid.time,EvidenceKind.Miracle,EvidenceSource.PlayerMiracle,CreatureAction.IdleOrObserve,"ground-whirlwind","Lifted and swirled free objects; cost per pulse "+miracles.EnergyCost(WhirlwindCost));IslandAudio.Cue(IslandSound.Gust,point,GetEntityId().GetHashCode(),.55f);}return true;}
 public bool ProcessWhirlwind(Vector3 point,bool held,float dt,bool aimValid=true){EnsureSeason();StopRain();StopWind();if(!held||Season.paused||miracles.Suspended||!HybridState.Number(dt,0,1)||dt<=0){Stop();return false;}heldFor+=Mathf.Min(dt,.1f);if(restRequired||heldFor>StrokeSeconds||strokePulses>=80){restRequired=true;StopWhirlwind();Reason="Release the trigger to rest the whirlwind";return false;}if(!miracles.CanAfford(WhirlwindCost)){restRequired=true;StopWhirlwind();Reason="Release the trigger: energy exhausted";return false;}string reason="";if(!aimValid||!CanWhirlwind(point,out reason)){StopWhirlwind();Reason=aimValid?reason:"Aim at island ground";return false;}bool applied=false;if(Season.Hybrid.time>=nextPulse){applied=WhirlwindPulse(point);if(applied)strokePulses++;}Active=true;Point=point;DrawWhirlwind(point);return applied;}
 void DrawWhirlwind(Vector3 point){for(int i=0;i<spiral.Length;i++){var line=spiral[i];line.enabled=true;line.transform.position=point;for(int j=0;j<64;j++){float t=j/63f;float a=t*Mathf.PI*5+Season.Hybrid.time*5+i*Mathf.PI*2/3;float radius=3+t*8;line.SetPosition(j,new Vector3(Mathf.Cos(a)*radius,t*20+.5f,Mathf.Sin(a)*radius)*nav.Scale);}}}
 void StopWhirlwind(){foreach(var line in spiral)if(line!=null)line.enabled=false;WhirlwindAffected=0;}
}
}
